"""Deterministic procedural multitrack fixtures (CC0, generated by this repo).

Each item has four ground-truth stems (vocals, drums, bass, other) synthesised from a
seed: kick/snare/hat synthesis, band-limited saw bass, additive electric-piano
chords, and formant-synthesised sung vowels. Every stem has one deliberately silent
bar so silent-target leakage can be measured.

These are NOT real recordings. Models trained on real music may treat them oddly
(e.g. formant "vocals"); results here are a sanity/regression signal, not a quality
verdict. Use them for CI, pipeline tests and gross failure detection.
"""
from __future__ import annotations

from dataclasses import dataclass

import numpy as np

SR = 44100
DEV_SEEDS = (0, 1, 2, 3)
HOLDOUT_SEEDS = (1000, 1001, 1002, 1003)

VOWELS = {  # (F1, F2, F3) Hz, rough adult formants
    "a": (800, 1150, 2900), "e": (400, 1600, 2700), "i": (350, 2300, 3000),
    "o": (450, 800, 2830), "u": (325, 700, 2530),
}
STEM_RMS_DB = {"vocals": -18.0, "drums": -18.0, "bass": -20.0, "other": -20.0}
SCALE = np.array([0, 2, 3, 5, 7, 8, 10])  # natural minor


@dataclass
class Item:
    id: str
    sample_rate: int
    stems: dict[str, np.ndarray]  # (2, n) float32
    license: str
    attribution: str

    @property
    def mixture(self) -> np.ndarray:
        return sum(self.stems.values())


def midi_hz(m: float) -> float:
    return 440.0 * 2 ** ((m - 69) / 12)


def saw(freq: float, n: int, rng: np.random.Generator, max_h: int = 40, rolloff: float = 1.0) -> np.ndarray:
    t = np.arange(n) / SR
    phase = rng.uniform(0, 2 * np.pi)
    out = np.zeros(n)
    for h in range(1, max_h + 1):
        if h * freq >= SR / 2 - 1000:
            break
        out += np.sin(2 * np.pi * h * freq * t + h * phase) / h ** rolloff
    return out


def env_adsr(n: int, a: float = 0.01, d: float = 0.15, s: float = 0.6, r: float = 0.08) -> np.ndarray:
    a_n, d_n, r_n = int(a * SR), int(d * SR), int(r * SR)
    sus = max(n - a_n - d_n - r_n, 0)
    e = np.concatenate([np.linspace(0, 1, a_n, endpoint=False), np.linspace(1, s, d_n, endpoint=False),
                        np.full(sus, s), np.linspace(s, 0, r_n)])
    return np.pad(e, (0, max(0, n - e.size)))[:n]


def resonator(x: np.ndarray, f: float, bw: float) -> np.ndarray:
    """Two-pole resonant band-pass (formant filter)."""
    from scipy.signal import lfilter
    r = np.exp(-np.pi * bw / SR)
    theta = 2 * np.pi * f / SR
    b = [1 - r]
    a = [1, -2 * r * np.cos(theta), r * r]
    return lfilter(b, a, x)


def pan(x: np.ndarray, p: float) -> np.ndarray:
    ang = (p + 1) * np.pi / 4
    return np.stack([x * np.cos(ang), x * np.sin(ang)])


def make_item(seed: int, seconds: float = 24.0) -> Item:
    rng = np.random.default_rng(seed)
    bpm = float(rng.uniform(84, 124))
    beat = 60.0 / bpm
    bar = 4 * beat
    n = int(seconds * SR)
    n_bars = int(seconds // bar)
    if n_bars < 5:
        raise ValueError(f"need >= 5 bars for per-stem silent bars; got {n_bars} at {bpm:.0f} bpm")
    root = int(rng.integers(40, 47))  # E2..B2 region
    prog = rng.choice(7, size=4, replace=True)
    prog[0] = 0
    silent_bar = {k: int(b) for k, b in zip(("vocals", "drums", "bass", "other"),
                                            rng.permutation(np.arange(1, n_bars))[:4])}

    def bar_span(b: int) -> tuple[int, int]:
        return int(b * bar * SR), int(min((b + 1) * bar * SR, n))

    # Drums
    drums = np.zeros(n)
    kick_len, snare_len, hat_len = int(0.35 * SR), int(0.25 * SR), int(0.06 * SR)
    tk = np.arange(kick_len) / SR
    kick = np.sin(2 * np.pi * np.cumsum(50 + 110 * np.exp(-tk * 30)) / SR) * np.exp(-tk * 9)
    ts = np.arange(snare_len) / SR
    snare_tone = 0.4 * np.sin(2 * np.pi * 185 * ts) * np.exp(-ts * 25)
    hat_pat = rng.random(8) < 0.85
    kick_pat = np.array([1, 0, 0, rng.random() < 0.5, 1, 0, rng.random() < 0.4, 0], bool)
    for b in range(n_bars):
        if b == silent_bar["drums"]:
            continue
        for step in range(8):
            pos = int((b * bar + step * beat / 2) * SR)
            if kick_pat[step]:
                seg = drums[pos:pos + kick_len]
                seg += kick[:seg.size] * 0.9
            if step in (2, 6):
                noise = rng.standard_normal(snare_len) * np.exp(-ts * 18)
                noise = resonator(noise, 2500, 3000) * 4
                seg = drums[pos:pos + snare_len]
                seg += (noise + snare_tone)[:seg.size] * 0.6
            if hat_pat[step]:
                h = np.diff(rng.standard_normal(hat_len + 1)) * np.exp(-np.arange(hat_len) / SR * 60)
                seg = drums[pos:pos + hat_len]
                seg += h[:seg.size] * 0.12

    # Bass and chords (one chord per bar)
    bass = np.zeros(n)
    keys = np.zeros((2, n))
    for b in range(n_bars):
        deg = int(prog[b % 4])
        chord_root = root + SCALE[deg]
        s0, s1 = bar_span(b)
        if b != silent_bar["bass"]:
            for k in range(4):
                if rng.random() < 0.15:
                    continue
                a = s0 + int(k * beat * SR)
                ln = int(beat * SR * 0.9)
                f = midi_hz(chord_root + (12 if rng.random() < 0.2 else 0))
                seg = bass[a:a + ln]
                tone = saw(f, ln, rng, max_h=25, rolloff=1.6) * env_adsr(ln, 0.005, 0.1, 0.7, 0.05)
                seg += tone[:seg.size] * 0.35
        if b != silent_bar["other"]:
            ln = s1 - s0
            chord = [chord_root + 12 + SCALE[(deg + i) % 7] - SCALE[deg] + (12 if (deg + i) >= 7 else 0)
                     for i in (0, 2, 4)]
            tone = np.zeros(ln)
            for m in chord:
                f = midi_hz(m + 12)
                t = np.arange(ln) / SR
                for h, amp in ((1, 1.0), (2, 0.5), (3, 0.25), (4, 0.12)):
                    tone += amp * np.sin(2 * np.pi * f * h * t) * np.exp(-t * (1.5 + h))
            keys[:, s0:s1] += pan(tone * 0.08, float(rng.uniform(-0.6, 0.6)))

    # Formant "vocals": phrases of sung syllables
    vox = np.zeros(n)
    for b in range(n_bars):
        if b == silent_bar["vocals"] or rng.random() < 0.15:
            continue
        s0, _ = bar_span(b)
        t_cursor = 0.0
        deg = int(prog[b % 4])
        while t_cursor < 3.5 * beat:
            dur = beat * float(rng.choice([0.5, 1.0, 1.5]))
            a = s0 + int(t_cursor * SR)
            ln = int(dur * SR * 0.92)
            m = root + 24 + SCALE[(deg + int(rng.choice([0, 2, 4, 7]))) % 7]
            t = np.arange(ln) / SR
            f0 = midi_hz(m) * (1 + 0.012 * np.sin(2 * np.pi * 5.5 * t) * np.clip(t * 3, 0, 1))
            ph = 2 * np.pi * np.cumsum(f0) / SR
            src = sum(np.sin(h * ph) / h for h in range(1, 30) if h * midi_hz(m) < 9000)
            src = src + 0.02 * rng.standard_normal(ln)
            f1, f2, f3 = VOWELS[str(rng.choice(list(VOWELS)))]
            y = resonator(src, f1, 80) + 0.6 * resonator(src, f2, 100) + 0.3 * resonator(src, f3, 140)
            y *= env_adsr(ln, 0.04, 0.1, 0.8, 0.06)
            seg = vox[a:a + ln]
            seg += y[:seg.size]
            t_cursor += dur
    vox = vox / (np.abs(vox).max() + 1e-9) * 0.5

    stems = {
        "vocals": pan(vox, 0.0),
        "drums": pan(drums, float(rng.uniform(-0.15, 0.15))),
        "bass": pan(bass, 0.0),
        "other": keys,
    }
    # Balance stems to fixed active-RMS targets (set after the first dev run showed
    # "other" ~21 dB and vocals ~9 dB below the mix), then normalise the mix peak.
    for k, v in stems.items():
        active = np.abs(v).max(axis=0) > 1e-4
        rms = np.sqrt(np.mean(v[:, active] ** 2)) if active.any() else 1.0
        stems[k] = v * (10 ** (STEM_RMS_DB[k] / 20) / max(rms, 1e-9))
    peak = np.abs(sum(stems.values())).max()
    scale = 0.8 / max(peak, 1e-9)
    stems = {k: (v * scale).astype(np.float32) for k, v in stems.items()}
    return Item(id=f"procedural-{seed}", sample_rate=SR, stems=stems,
                license="CC0-1.0", attribution="Generated by stemforge_bench.datasets.procedural")


def load(split: str) -> list[Item]:
    seeds = {"dev": DEV_SEEDS, "holdout": HOLDOUT_SEEDS}[split]
    return [make_item(s) for s in seeds]
